-- Auto Loader ingest of landing/transactions/<batch_id>/*.csv, all columns as text.
-- Same options as src/lib/autoloader.py: strings only (typing happens in Silver), addNewColumns schema
-- evolution, rescued data column. read_files exposes the file path via _metadata.
CREATE OR REFRESH STREAMING TABLE transactions_raw
COMMENT 'Raw card acquiring transactions loaded by Auto Loader from the landing volume. All columns are text as received. Synthetic data generated by dbldatagen. No real cardholder or merchant data.'
TBLPROPERTIES (
  'quality' = 'bronze',
  'data_classification' = 'confidential'
)
AS SELECT
  *,
  _metadata.file_path AS _source_file,
  current_timestamp() AS _ingested_at,
  regexp_extract(_metadata.file_path, '/transactions/([^/]+)/', 1) AS _batch_id
FROM STREAM read_files(
  '${merchant_monthly_totals.landing_root}/transactions/',
  format => 'csv',
  header => true,
  inferColumnTypes => false,
  schemaEvolutionMode => 'addNewColumns',
  rescuedDataColumn => '_rescued_data',
  pathGlobFilter => '*.csv'
);
